class Weight
  attr_reader :amount, :unit

  def initialize(amount, unit)
    @amount = amount
    @unit = unit
  end

  def <=>(other)
    raise ArgumentError, "Cannot compare different units" unless @unit == other.unit
    @amount <=> other.amount
  end

  def ==(other)
    @amount == other.amount && @unit == other.unit
  end

  def self.between(weight1, weight2, target)
    raise ArgumentError, "Cannot compare different units" unless weights_have_same_unit?(weight1, weight2, target)
    raise ArgumentError, "Order of boundaries must not matter" if weight1 > weight2
    target.amount >= weight1.amount && target.amount <= weight2.amount
  end

  def self.clamp(weight, lower, upper)
    raise ArgumentError, "Cannot compare or clamp with different unit" unless weights_have_same_unit?(lower, upper, weight)
    raise ArgumentError, "Order of boundaries must not matter" if lower > upper
    between_boundaries(lower.amount, upper.amount, weight.amount)
  end

  private

  def self.weights_have_same_unit?(a, b, c = nil)
    a.unit == b.unit && c.unit == a.unit if c
    a.unit == b.unit
  end

  def self.between_boundaries(low, up, value)
    value >= low && value <= up
  end
end
